"""Modern replacement for the Meridian CRM nightly case-escalation job."""

from datetime import datetime
from typing import Any


def _datediff(d1: Any, d2: Any) -> int:
    """Return whole calendar days d1 - d2 using legacy sentinel semantics."""
    if d1 in (None, "", "00000000") or d2 in (None, "", "00000000"):
        return 0

    first = datetime.strptime(str(d1), "%Y%m%d").date()
    second = datetime.strptime(str(d2), "%Y%m%d").date()
    return (first - second).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return workflow events for overdue live cases in CASE_ID order."""
    events: list[dict] = []

    for case in sorted(cases, key=lambda row: str(row.get("CASE_ID", ""))):
        if case.get("DEL_FLG", "") == "Y":
            continue

        status = case.get("STAT_CD", "")
        open_date = case.get("OPEN_DT", "")

        if status == "N" and _datediff(today, open_date) >= 2:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case.get("CASE_ID", "")),
                    "event": "auto_escalate",
                }
            )

        if (
            status == "A"
            and case.get("ESC_FLG", "") != "Y"
            and _datediff(today, open_date) >= 7
        ):
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case.get("CASE_ID", "")),
                    "event": "auto_escalate",
                }
            )

    return events
